1	// Package store owns the SQLite file and every write the service performs.
2	package store
3	
4	import (
5		"database/sql"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"slices"
10		"strings"
11		"time"
12	
13		_ "modernc.org/sqlite"
14	)
15	
16	// InitialStage is the stage every incident starts in when it is registered.
17	const InitialStage = "受理"
18	
19	// TimelineEntry records one stage of an incident's life together with the
20	// owner responsible at that point and the UTC time the entry was created.
21	type TimelineEntry struct {
22		Stage string `json:"stage"`
23		Owner string `json:"owner"`
24		At    string `json:"at"`
25	}
26	
27	// Incident is a registered ticket together with its full transition history.
28	type Incident struct {
29		ID       string          `json:"id"`
30		Severity string          `json:"severity"`
31		Assets   []string        `json:"assets"`
32		Stage    string          `json:"stage"`
33		Owner    string          `json:"owner"`
34		Timeline []TimelineEntry `json:"timeline"`
35	}
36	
37	// ErrIncidentConflict is returned when an id is registered again with
38	// different severity, assets, or owner.
39	var ErrIncidentConflict = errors.New("incident id already registered with different attributes")
40	
41	// ErrIncidentNotFound is returned when no incident exists for an id.
42	var ErrIncidentNotFound = errors.New("incident not found")
43	
44	// Store wraps the SQLite handle so callers never touch database/sql directly.
45	type Store struct {
46		db *sql.DB
47	}
48	
49	// Open prepares the database file and the schema this service needs.
50	func Open(path string) (*Store, error) {
51		db, err := sql.Open("sqlite", path)
52		if err != nil {
53			return nil, fmt.Errorf("open sqlite: %w", err)
54		}
55		if _, err := db.Exec("PRAGMA journal_mode=WAL"); err != nil {
56			db.Close()
57			return nil, fmt.Errorf("enable wal: %w", err)
58		}
59		if _, err := db.Exec(schema); err != nil {
60			db.Close()
61			return nil, fmt.Errorf("apply schema: %w", err)
62		}
63		return &Store{db: db}, nil
64	}
65	
66	// Ping reports whether the storage layer is usable.
67	func (s *Store) Ping() error { return s.db.Ping() }
68	
69	// Close releases the database handle.
70	func (s *Store) Close() error { return s.db.Close() }
71	
72	// Register stores a new incident and its initial timeline entry in one
73	// transaction. Re-registering the same id with identical severity, assets
74	// (order included), and owner returns the stored record unchanged; any
75	// difference yields ErrIncidentConflict.
76	func (s *Store) Register(id, severity, owner string, assets []string) (Incident, error) {
77		existing, err := s.find(id)
78		if err != nil {
79			return Incident{}, err
80		}
81		if existing != nil {
82			return resolveDuplicate(existing, severity, owner, assets)
83		}
84	
85		encoded, err := json.Marshal(assets)
86		if err != nil {
87			return Incident{}, fmt.Errorf("encode assets: %w", err)
88		}
89		at := time.Now().UTC().Format(time.RFC3339)
90	
91		tx, err := s.db.Begin()
92		if err != nil {
93			return Incident{}, fmt.Errorf("begin register: %w", err)
94		}
95		defer tx.Rollback()
96		if _, err = tx.Exec(
97			"INSERT INTO incidents (id, severity, assets, stage, owner) VALUES (?, ?, ?, ?, ?)",
98			id, severity, string(encoded), InitialStage, owner,
99		); err == nil {
100			if _, err = tx.Exec(
101				"INSERT INTO incident_timeline (incident_id, seq, stage, owner, at) VALUES (?, 0, ?, ?, ?)",
102				id, InitialStage, owner, at,
103			); err == nil {
104				err = tx.Commit()
105			}
106		}
107		if err != nil {
108			// A concurrent register of the same id may have won the race.
109			if existing, findErr := s.find(id); findErr == nil && existing != nil {
110				return resolveDuplicate(existing, severity, owner, assets)
111			}
112			return Incident{}, fmt.Errorf("register incident: %w", err)
113		}
114	
115		return Incident{
116			ID:       id,
117			Severity: severity,
118			Assets:   assets,
119			Stage:    InitialStage,
120			Owner:    owner,
121			Timeline: []TimelineEntry{{Stage: InitialStage, Owner: owner, At: at}},
122		}, nil
123	}
124	
125	// Get returns the incident registered under id, or ErrIncidentNotFound.
126	func (s *Store) Get(id string) (Incident, error) {
127		incident, err := s.find(id)
128		if err != nil {
129			return Incident{}, err
130		}
131		if incident == nil {
132			return Incident{}, ErrIncidentNotFound
133		}
134		return *incident, nil
135	}
136	
137	// List returns every incident matching the optional severity and stage
138	// filters, ordered by id in UTF-8 byte order. Empty filters match everything.
139	func (s *Store) List(severity, stage string) ([]Incident, error) {
140		query := "SELECT id, severity, assets, stage, owner FROM incidents"
141		var clauses []string
142		var args []any
143		if severity != "" {
144			clauses = append(clauses, "severity = ?")
145			args = append(args, severity)
146		}
147		if stage != "" {
148			clauses = append(clauses, "stage = ?")
149			args = append(args, stage)
150		}
151		if len(clauses) > 0 {
152			query += " WHERE " + strings.Join(clauses, " AND ")
153		}
154		query += " ORDER BY id"
155	
156		rows, err := s.db.Query(query, args...)
157		if err != nil {
158			return nil, fmt.Errorf("list incidents: %w", err)
159		}
160		incidents := []Incident{}
161		for rows.Next() {
162			incident, err := scanIncident(rows)
163			if err != nil {
164				rows.Close()
165				return nil, err
166			}
167			incidents = append(incidents, incident)
168		}
169		if err := rows.Err(); err != nil {
170			rows.Close()
171			return nil, fmt.Errorf("list incidents: %w", err)
172		}
173		rows.Close()
174	
175		for i := range incidents {
176			timeline, err := s.timeline(incidents[i].ID)
177			if err != nil {
178				return nil, err
179			}
180			incidents[i].Timeline = timeline
181		}
182		return incidents, nil
183	}
184	
185	// find loads one incident by id, returning nil when it does not exist.
186	func (s *Store) find(id string) (*Incident, error) {
187		row := s.db.QueryRow(
188			"SELECT id, severity, assets, stage, owner FROM incidents WHERE id = ?", id)
189		incident, err := scanIncident(row)
190		if errors.Is(err, sql.ErrNoRows) {
191			return nil, nil
192		}
193		if err != nil {
194			return nil, err
195		}
196		timeline, err := s.timeline(id)
197		if err != nil {
198			return nil, err
199		}
200		incident.Timeline = timeline
201		return &incident, nil
202	}
203	
204	// timeline loads the transition history of one incident in entry order.
205	func (s *Store) timeline(id string) ([]TimelineEntry, error) {
206		rows, err := s.db.Query(
207			"SELECT stage, owner, at FROM incident_timeline WHERE incident_id = ? ORDER BY seq", id)
208		if err != nil {
209			return nil, fmt.Errorf("read timeline: %w", err)
210		}
211		defer rows.Close()
212	
213		entries := []TimelineEntry{}
214		for rows.Next() {
215			var entry TimelineEntry
216			if err := rows.Scan(&entry.Stage, &entry.Owner, &entry.At); err != nil {
217				return nil, fmt.Errorf("read timeline: %w", err)
218			}
219			entries = append(entries, entry)
220		}
221		if err := rows.Err(); err != nil {
222			return nil, fmt.Errorf("read timeline: %w", err)
223		}
224		return entries, nil
225	}
226	
227	// resolveDuplicate decides whether a repeated registration is the same
228	// incident (returned unchanged) or a conflicting one.
229	func resolveDuplicate(existing *Incident, severity, owner string, assets []string) (Incident, error) {
230		if existing.Severity == severity && existing.Owner == owner && slices.Equal(existing.Assets, assets) {
231			return *existing, nil
232		}
233		return Incident{}, ErrIncidentConflict
234	}
235	
236	// scanner is the common shape of QueryRow/Query results over the incidents table.
237	type scanner interface {
238		Scan(dest ...any) error
239	}
240	
241	func scanIncident(row scanner) (Incident, error) {
242		var incident Incident
243		var encoded string
244		if err := row.Scan(&incident.ID, &incident.Severity, &encoded, &incident.Stage, &incident.Owner); err != nil {
245			return Incident{}, err
246		}
247		if err := json.Unmarshal([]byte(encoded), &incident.Assets); err != nil {
248			return Incident{}, fmt.Errorf("decode assets: %w", err)
249		}
250		return incident, nil
251	}
252	
253	const schema = `
254	CREATE TABLE IF NOT EXISTS service_metadata (
255		key   TEXT PRIMARY KEY,
256		value TEXT NOT NULL
257	);
258	CREATE TABLE IF NOT EXISTS incidents (
259		id       TEXT PRIMARY KEY,
260		severity TEXT NOT NULL,
261		assets   TEXT NOT NULL,
262		stage    TEXT NOT NULL,
263		owner    TEXT NOT NULL
264	);
265	CREATE TABLE IF NOT EXISTS incident_timeline (
266		incident_id TEXT NOT NULL REFERENCES incidents(id),
267		seq         INTEGER NOT NULL,
268		stage       TEXT NOT NULL,
269		owner       TEXT NOT NULL,
270		at          TEXT NOT NULL,
271		PRIMARY KEY (incident_id, seq)
272	);
273	`
274

